            }
        }
        v.sort();
        v
    };
    for target in [files[files.len() / 3].clone(), files[files.len() / 2].clone(), files[1].clone()] {
        let orig = std::fs::read_to_string(&target).unwrap();
        for i in 0..3 {
            std::fs::write(&target, format!("{orig}\n// edit {i}\n")).unwrap();
            let t = Instant::now();
            let u = s.update_file(&target);
